// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 v) internal {
        v = bound(v, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(v > 0);
        vm.assume(address(this).balance >= v);
        try c.addToBalance{value: v}() {} catch { return; }
        uint afterDeposit = address(c).balance;
        try c.withdrawBalance() {} catch { return; }
        assertTrue(address(c).balance + v == afterDeposit && c.getBalance(address(this)) == 0);
    }

    function testFuzz_run(uint256 v) public {
        _run(v);
    }

    receive() external payable {}
}
